#include <cmath>
#include <algorithm>
namespace{struct S{double x,y,z,vx,vy,vz,spin,rot;int stop;}s;inline double h(double a,double b){return std::sqrt(a*a+b*b);}}
extern "C"{void physics_step(double x,double y,double z,double vx,double vy,double vz,double spin,double rot,double tx,double ty,double dt,int mode){dt=std::clamp(dt,0.0,.05);s={x,y,z,vx,vy,vz,spin,rot,0};if(mode==0){s.vx=s.vy=s.vz=0;s.stop=1;return;}if(mode==1){double dx=tx-s.x,dy=ty-s.y,ax=dx*24.0-s.vx*9.2,ay=dy*24.0-s.vy*9.2,a=h(ax,ay);if(a>36){ax=ax/a*36;ay=ay/a*36;}s.vx+=ax*dt;s.vy+=ay*dt;double sp=h(s.vx,s.vy);if(sp>11.5){s.vx=s.vx/sp*11.5;s.vy=s.vy/sp*11.5;}s.z+=(0-s.z)*std::min(1.0,dt*14.0);s.vz=0;}else{bool air=s.z>.015||s.vz>.05;if(air){double d=std::exp(-.075*dt);s.vx*=d;s.vy*=d;if(std::abs(s.spin)>.001){double sp=h(s.vx,s.vy);if(sp>.2){double nx=-s.vy/sp,ny=s.vx/sp,a=std::min(7.5,std::abs(s.spin)*sp*.031),sg=s.spin<0?-1.0:1.0;s.vx+=nx*a*sg*dt;s.vy+=ny*a*sg*dt;s.spin*=std::exp(-.32*dt);}}s.vz-=16.8*dt;}else{double d=std::exp(-.31*dt);s.vx*=d;s.vy*=d;}}double ox=s.x,oy=s.y;s.x+=s.vx*dt;s.y+=s.vy*dt;s.z+=s.vz*dt;s.rot+=h(s.x-ox,s.y-oy)/.36;if(s.z<=0){if(s.vz<0){double imp=std::abs(s.vz);s.z=0;if(imp>1.15){s.vz=imp*.39;s.vx*=.93;s.vy*=.93;}else s.vz=0;}else s.z=0;}if(s.z>14){s.z=14;s.vz=std::min(0.0,s.vz);}if(mode==2&&s.z==0&&std::abs(s.vz)<.01&&h(s.vx,s.vy)<.14){s.vx=s.vy=s.vz=s.spin=0;s.stop=1;}}double physics_get_x(){return s.x;}double physics_get_y(){return s.y;}double physics_get_z(){return s.z;}double physics_get_vx(){return s.vx;}double physics_get_vy(){return s.vy;}double physics_get_vz(){return s.vz;}double physics_get_spin(){return s.spin;}double physics_get_rotation(){return s.rot;}int physics_is_stopped(){return s.stop;}}
